import{_ as s,o as e,c as n,a5 as t}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"61. 系统调用和标准库","description":"The Little Book of C 中文版 — 61. 系统调用和标准库","frontmatter":{"title":"61. 系统调用和标准库","date":"2026-07-04","lang":"zh-CN","categories":["C 教程"],"tags":["C","Little Book of C","07-贴近系统","中文"],"description":"The Little Book of C 中文版 — 61. 系统调用和标准库","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","translator":"机器辅助翻译（Google Translate）","section":61,"sidebarWeight":61,"alternateZh":"/posts/c教程/zh-CN/07-贴近系统/061-System Calls and the Standard Library","alternateEn":"/posts/c教程/en-US/07-Working Close to the System/061-System Calls and the Standard Library"},"headers":[],"relativePath":"posts/c教程/zh-CN/07-贴近系统/061-System Calls and the Standard Library.md","filePath":"posts/c教程/zh-CN/07-贴近系统/061-System Calls and the Standard Library.md","lastUpdated":1790163617000}'),p={name:"posts/c教程/zh-CN/07-贴近系统/061-System Calls and the Standard Library.md"};function l(i,a,o,d,c,r){return e(),n("div",null,[...a[0]||(a[0]=[t(`<p>[English version](/posts/c教程/en-US/07-Working Close to the System/061-System Calls and the Standard Library)</p><p>当您编写涉及文件、进程或设备的 C 程序时，您是在与操作系统对话，而不是直接与硬件对话。这种通信是通过系统调用进行的。</p><p>系统调用是用户空间程序和操作系统内核之间的最低级接口。 C 的标准库 (libc) 是构建在这些调用之上的一层薄薄的包装器，使它们更易于使用且更可移植。</p><p>让我们探讨一下它是如何工作的，以及如何直接从 C 代码使用系统调用。</p><h4 id="步骤-1-什么是系统调用" tabindex="-1">步骤 1. 什么是系统调用？ <a class="header-anchor" href="#步骤-1-什么是系统调用" aria-label="Permalink to &quot;步骤 1. 什么是系统调用？&quot;">​</a></h4><p>系统调用 (syscall) 允许程序向操作系统内核请求服务，例如读取文件、创建进程或分配内存。</p><p>示例：</p><p>-<code>read()</code>,<code>write()</code>– 访问文件和设备 -<code>fork()</code>,<code>exec()</code>– 创建和管理流程 -<code>open()</code>,<code>close()</code>– 处理文件描述符 -<code>mmap()</code>– 将文件映射到内存中 -<code>socket()</code>– 网络通讯</p><p>当您调用系统函数时，控制权从用户空间传递到内核空间，然后再返回。</p><h4 id="步骤-2-libc-的作用" tabindex="-1">步骤 2.libc 的作用 <a class="header-anchor" href="#步骤-2-libc-的作用" aria-label="Permalink to &quot;步骤 2.libc 的作用&quot;">​</a></h4><p>C 标准库（glibc、musl 等）提供了这些系统调用的包装器。</p><p>例子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    FILE *f = fopen(&quot;test.txt&quot;, &quot;r&quot;);</span></span>
<span class="line"><span>    if (!f) {</span></span>
<span class="line"><span>        perror(&quot;fopen failed&quot;);</span></span>
<span class="line"><span>        return 1;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    fclose(f);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>在引擎盖下，<code>fopen()</code>最终打电话<code>open()</code>，定义在的系统调用<code>&lt;fcntl.h&gt;</code>。也可以直接调用。</p><h4 id="步骤3-直接调用系统调用" tabindex="-1">步骤3.直接调用系统调用 <a class="header-anchor" href="#步骤3-直接调用系统调用" aria-label="Permalink to &quot;步骤3.直接调用系统调用&quot;">​</a></h4><p>这是没有 stdio 助手的相同操作：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;fcntl.h&gt;</span><span>     // open</span></span>
<span class="line"><span>#include &lt;unistd.h&gt;</span><span>    // read, write, close</span></span>
<span class="line"><span>#include &lt;stdio.h&gt;</span><span>     // perror</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int fd = open(&quot;test.txt&quot;, O_RDONLY);</span></span>
<span class="line"><span>    if (fd == -1) {</span></span>
<span class="line"><span>        perror(&quot;open failed&quot;);</span></span>
<span class="line"><span>        return 1;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    char buf[128];</span></span>
<span class="line"><span>    ssize_t n = read(fd, buf, sizeof(buf) - 1);</span></span>
<span class="line"><span>    if (n &gt;= 0) {</span></span>
<span class="line"><span>        buf[n] = &#39;\\0&#39;;</span></span>
<span class="line"><span>        write(STDOUT_FILENO, buf, n);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    close(fd);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>编译并运行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc sysread.c -o sysread</span></span>
<span class="line"><span>./sysread</span></span></code></pre></div><p>这将打印前 128 个字节<code>test.txt</code>直接使用系统调用，没有<code>fopen()</code>或者<code>printf()</code>涉及。</p><h4 id="小代码-最小系统调用示例" tabindex="-1">小代码：最小系统调用示例 <a class="header-anchor" href="#小代码-最小系统调用示例" aria-label="Permalink to &quot;小代码：最小系统调用示例&quot;">​</a></h4><p>让我们甚至放弃 C 库并使用原始系统调用接口。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;unistd.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    const char msg[] = &quot;Hello via system call\\n&quot;;</span></span>
<span class="line"><span>    write(1, msg, sizeof(msg) - 1);  // 1 = STDOUT</span></span>
<span class="line"><span>    _exit(0);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>编译：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -nostdlib -static syshello.c -o syshello</span></span></code></pre></div><p>跑步：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Hello via system call</span></span></code></pre></div><p>您只是直接执行系统调用，完全绕过标准库。</p><h4 id="步骤-4-文件描述符" tabindex="-1">步骤 4. 文件描述符 <a class="header-anchor" href="#步骤-4-文件描述符" aria-label="Permalink to &quot;步骤 4. 文件描述符&quot;">​</a></h4><p>系统调用如<code>read()</code>和<code>write()</code>使用文件描述符，由操作系统管理的小整数句柄。</p><table tabindex="0"><thead><tr><th>描述符</th><th>意义</th></tr></thead><tbody><tr><td>0</td><td>标准输入（<code>stdin</code>)</td></tr><tr><td>1</td><td>标准输出（<code>stdout</code>)</td></tr><tr><td>2</td><td>标准误（<code>stderr</code>)</td></tr></tbody></table><p>每个打开的文件、套接字或管道都有一个唯一的描述符。</p><p>例子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>write(1, &quot;Output to stdout\\n&quot;, 17);</span></span>
<span class="line"><span>write(2, &quot;Output to stderr\\n&quot;, 17);</span></span></code></pre></div><h4 id="步骤-5-检查系统调用" tabindex="-1">步骤 5. 检查系统调用 <a class="header-anchor" href="#步骤-5-检查系统调用" aria-label="Permalink to &quot;步骤 5. 检查系统调用&quot;">​</a></h4><p>您可以使用以下方式观看程序的系统调用<code>strace</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>strace ./sysread</span></span></code></pre></div><p>输出示例：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>open(&quot;test.txt&quot;, O_RDONLY) = 3</span></span>
<span class="line"><span>read(3, &quot;Hello World\\n&quot;, 12) = 12</span></span>
<span class="line"><span>write(1, &quot;Hello World\\n&quot;, 12) = 12</span></span>
<span class="line"><span>close(3) = 0</span></span></code></pre></div><p>这展示了真正的内核级操作，是一个很棒的调试和学习工具。</p><h4 id="步骤-6-返回值和错误" tabindex="-1">步骤 6. 返回值和错误 <a class="header-anchor" href="#步骤-6-返回值和错误" aria-label="Permalink to &quot;步骤 6. 返回值和错误&quot;">​</a></h4><p>系统调用通常返回：</p><ul><li>≥ 0 → 成功（读取的字节数、进程 ID 等）</li><li>-1 → 错误（与<code>errno</code>设置为错误代码）</li></ul><p>例子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;errno.h&gt;</span></span>
<span class="line"><span>#include &lt;string.h&gt;</span></span>
<span class="line"><span>int fd = open(&quot;missing.txt&quot;, O_RDONLY);</span></span>
<span class="line"><span>if (fd == -1)</span></span>
<span class="line"><span>    fprintf(stderr, &quot;Error: %s\\n&quot;, strerror(errno));</span></span></code></pre></div><p>常见错误代码：</p><table tabindex="0"><thead><tr><th>代码</th><th>意义</th></tr></thead><tbody><tr><td><code>ENOENT</code></td><td>找不到文件</td></tr><tr><td><code>EACCES</code></td><td>权限被拒绝</td></tr><tr><td><code>EBADF</code></td><td>无效描述符</td></tr><tr><td><code>EINTR</code></td><td>系统调用中断</td></tr></tbody></table><h4 id="步骤-7-混合系统调用和-stdio" tabindex="-1">步骤 7. 混合系统调用和 stdio <a class="header-anchor" href="#步骤-7-混合系统调用和-stdio" aria-label="Permalink to &quot;步骤 7. 混合系统调用和 stdio&quot;">​</a></h4><p>您可以安全地组合两个层，只是不要将它们混合在同一个文件描述符上。</p><p>示例（安全）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>FILE *f = fopen(&quot;log.txt&quot;, &quot;w&quot;);</span></span>
<span class="line"><span>write(STDOUT_FILENO, &quot;Console log\\n&quot;, 12);</span></span>
<span class="line"><span>fprintf(f, &quot;File log\\n&quot;);</span></span>
<span class="line"><span>fclose(f);</span></span></code></pre></div><p>示例（不安全）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>FILE *f = fopen(&quot;data.txt&quot;, &quot;w&quot;);</span></span>
<span class="line"><span>write(fileno(f), &quot;mixed output\\n&quot;, 13);  // may confuse buffering</span></span></code></pre></div><h4 id="步骤-8-系统调用包装器" tabindex="-1">步骤 8. 系统调用包装器 <a class="header-anchor" href="#步骤-8-系统调用包装器" aria-label="Permalink to &quot;步骤 8. 系统调用包装器&quot;">​</a></h4><p>Linux 内核提供了数百个系统调用。您可以通过以下方式拨打大部分电话：<code>&lt;unistd.h&gt;</code>，但对于罕见的，你可以使用<code>syscall()</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;sys/syscall.h&gt;</span></span>
<span class="line"><span>#include &lt;unistd.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    syscall(SYS_write, 1, &quot;Hello syscall\\n&quot;, 14);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><h4 id="步骤-9-查看可用的系统调用" tabindex="-1">步骤 9. 查看可用的系统调用 <a class="header-anchor" href="#步骤-9-查看可用的系统调用" aria-label="Permalink to &quot;步骤 9. 查看可用的系统调用&quot;">​</a></h4><p>检查您的平台的所有可用系统调用：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>man 2 intro</span></span></code></pre></div><p>或者</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ausyscall --dump | head</span></span></code></pre></div><p>您会看到如下列表：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>read, write, open, close, stat, fork, execve, mmap, ...</span></span></code></pre></div><h4 id="第-10-步-为什么它很重要" tabindex="-1">第 10 步：为什么它很重要 <a class="header-anchor" href="#第-10-步-为什么它很重要" aria-label="Permalink to &quot;第 10 步：为什么它很重要&quot;">​</a></h4><p>系统调用是 C 和类 Unix 系统中一切的基础。</p><p>它们使您的程序可以直接访问：</p><ul><li>文件和设备</li><li>进程和信号</li><li>内存和网络</li><li>时间和环境</li></ul><p>学习直接使用它们对于理解更高级别的抽象（例如<code>stdio</code>,<code>pthreads</code>，或套接字）已构建。</p><h4 id="自己尝试一下" tabindex="-1">自己尝试一下 <a class="header-anchor" href="#自己尝试一下" aria-label="Permalink to &quot;自己尝试一下&quot;">​</a></h4><ol><li>使用<code>strace</code>在<code>ls</code>或者<code>cat</code>看看系统调用如何驱动它们。</li><li>更换一个<code>fopen()</code>/<code>fread()</code>与直接配对<code>open()</code>和<code>read()</code>来电。</li><li>编写一个小型文件复制器，仅使用<code>open</code>,<code>read</code>,<code>write</code>， 和<code>close</code>.</li><li>尝试无效的文件描述符并打印出来<code>errno</code>.</li><li>构建一个版本<code>echo</code>仅使用原始系统调用。</li></ol><p>接下来，您将更进一步：学习如何创建和管理流程<code>fork()</code>和<code>exec()</code>，Unix 多任务处理的核心。</p>`,71)])])}const b=s(p,[["render",l]]);export{u as __pageData,b as default};
